import re

def roman_to_int_strict(s: str) -> int:
    roman_dict = {
        'M': 1000, 'CM': 900, 'D': 100, 'CD': 400, 'C': 100, 'XC': 90, 'L': 50, 'XL': 40, 'X': 10, 'IX': 9, 'V': 5, 'IV': 4, 'I': 1
    }

    result = 0
    for char in s:
        num = roman_dict.get(char, 0)
        if num == 0:
            return -1  # Invalid Roman numeral
        result += num

    return result
